import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem112 preserva dados operacionais',()=>{for(const [n,titulo,expected,link] of [["6989366460","Tênis Feminino Casual Confortavel Plataforma Tratorado","Tênis casual feminino Amoli com plataforma tratorada","https://produto.mercadolivre.com.br/MLB-6989366460-tnis-feminino-casual-confortavel-plataforma-tratorado-_JM?searchVariation=204226326167"],["7011230810","Mini Impressora Térmica 58mm Portátil Usb E Bluetooth Fatura","Mini impressora térmica de 58 mm — USB e Bluetooth anunciados","https://www.mercadolivre.com.br/up/MLBU4128815687?pdp_filters=item_id%3AMLB7011230810"],["7174618968","Mouse Gamer Branco Profissional Ultra Leve Slits V2 7200 Dpi","Mouse Slits V2 branco com fio — 7.200 DPI anunciados","https://www.mercadolivre.com.br/up/MLBU4333768740?pdp_filters=item_id%3AMLB7174618968"]]){const p={id:'mlMLB'+n,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
